This function is getting long and hard to read. Can you extract the address validation bit into its own method? It shouldn't change what the function does, just make it easier to follow.

```python
def register_user(payload: dict) -> User:
    if not payload.get('email') or '@' not in payload['email']:
        raise ValueError('invalid email')
    if not payload.get('name') or len(payload['name']) < 2:
        raise ValueError('invalid name')

    addr = payload.get('address', {})
    if not addr.get('street'):
        raise ValueError('street required')
    if not addr.get('city'):
        raise ValueError('city required')
    if not addr.get('zip') or not addr['zip'].isdigit() or len(addr['zip']) != 5:
        raise ValueError('invalid zip')
    if addr.get('country', 'US') not in ('US', 'CA', 'MX'):
        raise ValueError('unsupported country')

    user = User(email=payload['email'], name=payload['name'], address=Address(**addr))
    return user
